import { joinPrivateArray, mapPrivateArray } from "../security/private-array.js";
import { defineSchema } from "../schemas/index.js";
const NATIVE_TEXT_ATTACHMENT_EXTENSIONS = [
    ".txt",
    ".md",
    ".json",
    ".xml",
    ".html",
    ".css",
    ".js",
    ".mjs",
    ".cjs",
    ".ts",
    ".mts",
    ".cts",
    ".jsx",
    ".tsx",
    ".py",
    ".java",
    ".cpp",
    ".c",
    ".h",
    ".php",
    ".rb",
    ".go",
    ".rs",
    ".swift",
    ".kt",
    ".scala",
    ".sh",
    ".yaml",
    ".yml",
    ".toml",
    ".ini",
    ".cfg",
    ".conf",
    ".sql",
];
/** File extensions that chat uploads can inline as text. */
export const textFileExtensions = [...NATIVE_TEXT_ATTACHMENT_EXTENSIONS, ".csv"];
/** Image media types that chat uploads can display natively. */
export const imageFileTypes = [
    "image/png",
    "image/jpeg",
    "image/jpg",
    "image/gif",
    "image/webp",
    "image/bmp",
    "image/tiff",
];
const INLINE_TEXT_MEDIA_TYPE = "text/plain";
const INLINE_BINARY_MEDIA_TYPE = "application/octet-stream";
const INLINE_PDF_MEDIA_TYPE = "application/pdf";
/** Zod schema for get chat request context. */
export const getChatRequestContextSchema = defineSchema((v) => v.object({
    conversationId: v.string().optional(),
    projectId: v.string().nullable(),
    projectSlug: v.string().optional(),
    branchId: v.string().nullable(),
    runtimeTargetKind: v.enum(["main_branch", "environment", "preview_branch"])
        .nullable()
        .optional(),
    runtimeTargetEnvironmentId: v.string().uuid().nullable().optional(),
    environmentContext: v.string().optional(),
}).strict());
// Helper that returns a nonEmptyString schema for reuse within defineSchema callbacks.
const nonEmptyString = (v) => v.string().min(1);
const getChildRunAuditStatusSchema = defineSchema((v) => v.enum(["completed", "failed", "cancelled", "stopped"]));
const getChildRunAuditToolCallSchema = defineSchema((v) => v.object({
    toolName: v.string(),
    toolCallId: v.string(),
    input: v.unknown().optional(),
}).strict());
const getChildRunAuditToolResultSchema = defineSchema((v) => v.object({
    toolName: v.string(),
    toolCallId: v.string(),
    input: v.unknown(),
    output: v.unknown(),
}).strict());
const getChildRunAuditSchema = defineSchema((v) => v.object({
    status: getChildRunAuditStatusSchema(),
    description: v.string().optional(),
    steps: v.number().int().nonnegative().optional(),
    durationMs: v.number().nonnegative().optional(),
    toolCalls: v.array(getChildRunAuditToolCallSchema()).optional(),
    toolResults: v.array(getChildRunAuditToolResultSchema()).optional(),
    terminalErrorCode: v.string().nullable().optional(),
    terminalErrorMessage: v.string().nullable().optional(),
}).strict());
const getMessageMetadataUsageSchema = defineSchema((v) => v.object({
    inputTokens: v.number().int().nonnegative().optional(),
    outputTokens: v.number().int().nonnegative().optional(),
    reasoningTokens: v.number().int().nonnegative().optional(),
    cachedInputTokens: v.number().int().nonnegative().optional(),
    cacheCreationInputTokens: v.number().int().nonnegative().optional(),
    cacheCreation1hInputTokens: v.number().int().nonnegative().optional(),
    cacheReadInputTokens: v.number().int().nonnegative().optional(),
}).strict());
/** Zod schema for get message metadata. */
export const getMessageMetadataSchema = defineSchema((v) => v.object({
    createdAt: v.string().optional(),
    isStopped: v.boolean().optional(),
    isCompleted: v.boolean().optional(),
    completedAt: v.string().optional(),
    agentId: v.string().optional(),
    agentName: v.string().optional(),
    agentAvatarUrl: v.string().url().optional(),
    conversationId: v.string().optional(),
    modelId: v.string().optional(),
    runId: v.string().optional(),
    streamingMessageId: v.string().optional(),
    childRunAudit: getChildRunAuditSchema().optional(),
    usage: getMessageMetadataUsageSchema().optional(),
    billableInputTokens: v.number().int().nonnegative().optional(),
    billableOutputTokens: v.number().int().nonnegative().optional(),
    costUsd: v.number().nonnegative().optional(),
    providerInputCostUsd: v.number().nonnegative().optional(),
    providerOutputCostUsd: v.number().nonnegative().optional(),
    providerCostUsd: v.number().nonnegative().optional(),
    veryfrontInputChargeUsd: v.number().nonnegative().optional(),
    veryfrontOutputChargeUsd: v.number().nonnegative().optional(),
    veryfrontChargeUsd: v.number().nonnegative().optional(),
    veryfrontBilledUsd: v.number().nonnegative().optional(),
    costCredits: v.number().nonnegative().optional(),
    costSource: v.enum(["gateway", "missing", "partial"]).optional(),
    billingMode: v.enum(["direct", "deferred"]).optional(),
    usageCaptureStatus: v.enum(["complete", "partial", "missing"]).optional(),
}).strict());
/** Zod schema for get chat UI message role. */
export const getChatUiMessageRoleSchema = defineSchema((v) => v.enum(["system", "user", "assistant", "tool"]));
/** Zod schema for get chat tool part state. */
export const getChatToolPartStateSchema = defineSchema((v) => v.enum([
    "pending",
    "input-streaming",
    "input-available",
    "approval-requested",
    "approval-responded",
    "output-available",
    "output-error",
    "output-denied",
    "error",
    "completed",
]));
const getToolApprovalSchema = defineSchema((v) => v.object({
    id: nonEmptyString(v),
}).strict());
const getToolPartBaseSchema = defineSchema((v) => v.object({
    toolCallId: nonEmptyString(v),
    input: v.unknown(),
    state: getChatToolPartStateSchema(),
    title: nonEmptyString(v).optional(),
    providerExecuted: v.boolean().optional(),
    callProviderMetadata: v.record(v.string(), v.unknown()).optional(),
    output: v.unknown().optional(),
    errorText: nonEmptyString(v).optional(),
    approval: getToolApprovalSchema().optional(),
}).strip());
const getChatTextUiPartSchema = defineSchema((v) => v.object({
    type: v.literal("text"),
    text: v.string(),
}).strip());
const getChatReasoningUiPartSchema = defineSchema((v) => v.object({
    type: v.literal("reasoning"),
    text: v.string(),
    signature: v.string().optional(),
    redactedData: v.string().optional(),
}).strip());
const getChatStepStartUiPartSchema = defineSchema((v) => v.object({
    type: v.literal("step-start"),
}).strip());
const getChatSourceUrlUiPartSchema = defineSchema((v) => v.object({
    type: v.literal("source-url"),
    sourceId: nonEmptyString(v),
    url: nonEmptyString(v),
    title: v.string().optional(),
}).strip());
const getChatSourceDocumentUiPartSchema = defineSchema((v) => v.object({
    type: v.literal("source-document"),
    sourceId: nonEmptyString(v),
    title: nonEmptyString(v),
    mediaType: nonEmptyString(v).optional(),
    filename: nonEmptyString(v).optional(),
}).strip());
const getFileUiPartWithUploadSchema = defineSchema((v) => v.object({
    type: v.literal("file"),
    mediaType: nonEmptyString(v),
    url: nonEmptyString(v),
    filename: nonEmptyString(v).optional(),
    size: v.number().int().nonnegative().optional(),
    uploadId: nonEmptyString(v).optional(),
    uploadPath: nonEmptyString(v).optional(),
}).strip());
const getChatDynamicToolUiPartSchema = defineSchema((v) => getToolPartBaseSchema().extend({
    type: v.literal("dynamic-tool"),
    toolName: nonEmptyString(v),
}));
const getChatNamedToolTypeSchema = defineSchema((v) => v.custom((value) => typeof value === "string" && (value === "tool_call" || /^tool-.+$/u.test(value))));
const getChatNamedToolUiPartSchema = defineSchema((v) => getToolPartBaseSchema().extend({
    type: getChatNamedToolTypeSchema(),
    toolName: nonEmptyString(v).optional(),
}));
const getChatDataUiPartTypeSchema = defineSchema((v) => v.custom((value) => typeof value === "string" && /^data-.+$/u.test(value)));
const getChatDataUiPartSchema = defineSchema((v) => v.object({
    type: getChatDataUiPartTypeSchema(),
    data: v.unknown(),
}).strip());
/** Zod schema for get chat UI message part. */
export const getChatUiMessagePartSchema = defineSchema((v) => v.union([
    getChatTextUiPartSchema(),
    getChatReasoningUiPartSchema(),
    getChatStepStartUiPartSchema(),
    getChatSourceUrlUiPartSchema(),
    getChatSourceDocumentUiPartSchema(),
    getFileUiPartWithUploadSchema(),
    getChatDynamicToolUiPartSchema(),
    getChatNamedToolUiPartSchema(),
    getChatDataUiPartSchema(),
]));
/** Zod schema for get chat UI message. */
export const getChatUiMessageSchema = defineSchema((v) => v.object({
    id: nonEmptyString(v),
    role: getChatUiMessageRoleSchema(),
    parts: v.array(getChatUiMessagePartSchema()),
    metadata: getMessageMetadataSchema().optional(),
}).strip());
/** Zod schema for get chat UI messages. */
export const getChatUiMessagesSchema = defineSchema((v) => v.array(getChatUiMessageSchema()));
function hasExtension(filename, extensions) {
    const normalizedFilename = filename?.toLowerCase() ?? "";
    return extensions.some((extension) => normalizedFilename.endsWith(extension));
}
function isNativeTextAttachmentFile(filename) {
    return hasExtension(filename, NATIVE_TEXT_ATTACHMENT_EXTENSIONS);
}
function preferNativeTextAttachmentMediaType(filename, fallbackMediaType) {
    return isNativeTextAttachmentFile(filename) ? INLINE_TEXT_MEDIA_TYPE : fallbackMediaType;
}
function isTextMediaType(type) {
    return type?.startsWith("text/") ?? false;
}
function isInlinePreviewMediaType(mediaType) {
    return isTextMediaType(mediaType) || isImageFile(mediaType) ||
        mediaType === INLINE_PDF_MEDIA_TYPE;
}
/** Check whether a file is an image. */
export function isImageFile(type) {
    return type?.startsWith("image/") ?? false;
}
/** Check whether a file is a supported image upload. */
export function isValidImageFile(type) {
    if (type.length === 0) {
        return false;
    }
    return imageFileTypes.some((imageFileType) => imageFileType === type);
}
/** Check whether a file supports text preview. */
export function isTextPreviewFile(name, type) {
    return isTextMediaType(type) || hasExtension(name, textFileExtensions);
}
/** Normalizes inline attachment media type. */
export function normalizeInlineAttachmentMediaType(filename, mediaType) {
    if (!mediaType) {
        return preferNativeTextAttachmentMediaType(filename, INLINE_BINARY_MEDIA_TYPE);
    }
    if (isInlinePreviewMediaType(mediaType)) {
        return mediaType;
    }
    return preferNativeTextAttachmentMediaType(filename, mediaType);
}
function escapeXmlAttr(value) {
    let escaped = "";
    for (let index = 0; index < value.length; index++) {
        const character = value[index];
        switch (character) {
            case "&":
                escaped += "&amp;";
                break;
            case '"':
                escaped += "&quot;";
                break;
            case "<":
                escaped += "&lt;";
                break;
            case ">":
                escaped += "&gt;";
                break;
            default:
                escaped += character;
        }
    }
    return escaped;
}
/** Builds data file annotation. */
export function buildDataFileAnnotation(refs) {
    if (refs.length === 0)
        return "";
    const fileTags = joinPrivateArray(mapPrivateArray(refs, (ref) => {
        let attrs = `name="${escapeXmlAttr(ref.name)}"`;
        if (ref.uploadId)
            attrs += ` upload_id="${escapeXmlAttr(ref.uploadId)}"`;
        if (ref.path)
            attrs += ` path="${escapeXmlAttr(ref.path)}"`;
        if (typeof ref.size === "number")
            attrs += ` size="${ref.size}"`;
        if (ref.url)
            attrs += ` url="${escapeXmlAttr(ref.url)}"`;
        attrs += ` type="${escapeXmlAttr(ref.mediaType)}"`;
        return `<file ${attrs} />`;
    }), "\n");
    return `\n\n<uploaded_files>\n${fileTags}\n</uploaded_files>`;
}
